20	/// The cost of a line or inline layout.
21	type Cost = f64;
22	
23	// Cost parameters.
24	//
25	// We choose higher costs than the Knuth-Plass paper (which would be 50) because
26	// it hyphenates way to eagerly in Typst otherwise. Could be related to the
27	// ratios coming out differently since Typst doesn't have the concept of glue,
28	// so things work a bit differently.
29	const DEFAULT_HYPH_COST: Cost = 135.0;
30	const DEFAULT_RUNT_COST: Cost = 100.0;
31	
32	// Other parameters.
33	const MIN_RATIO: f64 = -1.0;
34	const MIN_APPROX_RATIO: f64 = -0.5;
35	const BOUND_EPS: f64 = 1e-3;
36	
37	/// The general line break segmenter.
38	static SEGMENTER: LazyLock<LineSegmenterBorrowed> =
39	    LazyLock::new(|| LineSegmenter::new_lstm(LineBreakOptions::default()));
40	
41	/// The line break segmenter for Chinese/Japanese text.
42	///
43	/// This is generated by manually overriding the line break properties for curly
44	/// quotes `U+201C` and `U+201D` from `QU` (`Quotation`) to `OP`
45	/// (`OpenPunctuation`) and `CP` (`CloseParenthesis`), respectively.
46	///
47	/// This can be combined with [`SEGMENTER`] once ICU4X updates the line
48	/// segmenter to Unicode 17.0. This will also allow us to remove the `serde`
49	/// feature from the dependency.
50	static CJ_SEGMENTER: LazyLock<LineSegmenter> = LazyLock::new(|| {
51	    let blob = typst_assets::icu::ICU_CJ_SEGMENT;
52	    let cj_provider = BlobDataProvider::try_new_from_static_blob(blob).unwrap();
53	    LineSegmenter::try_new_for_non_complex_scripts_with_buffer_provider(
54	        &cj_provider,
55	        LineBreakOptions::default(),
56	    )
57	    .unwrap()
58	});
