60	/// The Unicode line break properties for each code point.
61	const LINEBREAK_DATA: CodePointMapDataBorrowed<LineBreak> =
62	    CodePointMapDataBorrowed::new();
63	
64	/// A line break opportunity.
65	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
66	pub enum Breakpoint {
67	    /// Just a normal opportunity (e.g. after a space).
68	    Normal,
69	    /// A mandatory breakpoint (after '\n' or at the end of the text).
70	    Mandatory,
71	    /// An opportunity for hyphenating and how many chars are before/after it
72	    /// in the word.
73	    Hyphen(u8, u8),
74	}
75	
76	impl Breakpoint {
77	    /// Trim a line before this breakpoint.
78	    pub fn trim(self, start: usize, line: &str) -> Trim {
79	        match self {
80	            // Trailing whitespace should be shaped, but the glyphs should have
81	            // their advance width zeroed. This way, they are available for copy
82	            // paste, but don't influence layout.
83	            // Also trim Unicode `Default_Ignorable`s, since they may interfere
84	            // with end-of-line adjustments in CJK layout and since they are not
85	            // rendered, they will be included in another glyph cluster. If they
86	            // aren't trimmed here and they attach to a space glyph that is
87	            // covered by a font, the space may be considered relevant for
88	            // inline layout, which is undesirable. Unicode `Default_Ignorable`s
89	            // include among others:
90	            // - `\u{200B}` zero width space
91	            // - `\u{202A}` LTR embedding
92	            // - `\u{202B}` RTL embedding
93	            // - `\u{202C}` POP embedding
94	            // - `\u{2066}` LTR isolate
95	            // - `\u{2069}` POP isolate
96	            Self::Normal => {
97	                let trimmed = line.trim_end_matches(|c: char| {
98	                    c.is_whitespace() || is_default_ignorable(c)
99	                });
100	                Trim {
101	                    layout: start + trimmed.len(),
102	                    shaping: start + line.len(),
103	                }
104	            }
105	
106	            // Trim linebreaks.
107	            Self::Mandatory => {
108	                let trimmed = line.trim_end_matches(|c| {
109	                    matches!(
110	                        LINEBREAK_DATA.get(c),
111	                        LineBreak::MandatoryBreak
112	                            | LineBreak::CarriageReturn
113	                            | LineBreak::LineFeed
114	                            | LineBreak::NextLine
115	                    )
116	                });
117	                Trim::uniform(start + trimmed.len())
118	            }
119	
120	            // Trim nothing.
121	            Self::Hyphen(..) => Trim::uniform(start + line.len()),
122	        }
123	    }
124	
125	    /// Whether this is a hyphen breakpoint.
126	    pub fn is_hyphen(self) -> bool {
127	        matches!(self, Self::Hyphen(..))
128	    }
129	}
