131	/// How to trim the end of a line.
132	///
133	/// It's an invariant that `self.layout <= self.shaping`.
134	pub struct Trim {
135	    /// The text in the range `layout..shaping` should be shaped but should not
136	    /// affect layout. This ensures that we trim spaces for layout purposes, but
137	    /// still render zero-advance space glyphs for copy paste.
138	    pub layout: usize,
139	    /// The text should only be shaped up until the given text offset. Newlines
140	    /// are already trimmed here.
141	    pub shaping: usize,
142	}
143	
144	impl Trim {
145	    /// Create an instance with equal layout and shaping trim.
146	    fn uniform(trim: usize) -> Self {
147	        Self { layout: trim, shaping: trim }
148	    }
149	}
