151	/// Breaks the text into lines.
152	pub fn linebreak<'a>(
153	    engine: &Engine,
154	    p: &'a Preparation<'a>,
155	    width: Abs,
156	) -> Vec<Line<'a>> {
157	    match p.config.linebreaks {
158	        Linebreaks::Simple => linebreak_simple(engine, p, width),
159	        Linebreaks::Optimized => linebreak_optimized(engine, p, width),
160	    }
161	}
162	
163	/// Performs line breaking in simple first-fit style. This means that we build
164	/// lines greedily, always taking the longest possible line. This may lead to
165	/// very unbalanced line, but is fast and simple.
166	#[typst_macros::time]
167	fn linebreak_simple<'a>(
168	    engine: &Engine,
169	    p: &'a Preparation<'a>,
170	    width: Abs,
171	) -> Vec<Line<'a>> {
172	    let mut lines = Vec::with_capacity(16);
173	    let mut start = 0;
174	    let mut last = None;
175	
176	    breakpoints(p, |end, breakpoint| {
177	        // Compute the line and its size.
178	        let mut attempt = line(engine, p, start..end, breakpoint, lines.last());
179	
180	        // If the line doesn't fit anymore, we push the last fitting attempt
181	        // into the stack and rebuild the line from the attempt's end. The
182	        // resulting line cannot be broken up further.
183	        if !width.fits(attempt.width)
184	            && let Some((last_attempt, last_end)) = last.take()
185	        {
186	            lines.push(last_attempt);
187	            start = last_end;
188	            attempt = line(engine, p, start..end, breakpoint, lines.last());
189	        }
190	
191	        // Finish the current line if there is a mandatory line break (i.e. due
192	        // to "\n") or if the line doesn't fit horizontally already since then
193	        // no shorter line will be possible.
194	        if breakpoint == Breakpoint::Mandatory || !width.fits(attempt.width) {
195	            lines.push(attempt);
196	            start = end;
197	            last = None;
198	        } else {
199	            last = Some((attempt, end));
200	        }
201	    });
202	
203	    if let Some((line, _)) = last {
204	        lines.push(line);
205	    }
206	
207	    lines
208	}
