210	/// Performs line breaking in optimized Knuth-Plass style. Here, we use more
211	/// context to determine the line breaks than in the simple first-fit style. For
212	/// example, we might choose to cut a line short even though there is still a
213	/// bit of space to improve the fit of one of the following lines. The
214	/// Knuth-Plass algorithm is based on the idea of "cost". A line which has a
215	/// very tight or very loose fit has a higher cost than one that is just right.
216	/// Ending a line with a hyphen incurs extra cost and endings two successive
217	/// lines with hyphens even more.
218	///
219	/// To find the layout with the minimal total cost the algorithm uses dynamic
220	/// programming: For each possible breakpoint, it determines the optimal layout
221	/// _up to that point_. It walks over all possible start points for a line
222	/// ending at that point and finds the one for which the cost of the line plus
223	/// the cost of the optimal layout up to the start point (already computed and
224	/// stored in dynamic programming table) is minimal. The final result is simply
225	/// the layout determined for the last breakpoint at the end of text.
226	#[typst_macros::time]
227	fn linebreak_optimized<'a>(
228	    engine: &Engine,
229	    p: &'a Preparation<'a>,
230	    width: Abs,
231	) -> Vec<Line<'a>> {
232	    let metrics = CostMetrics::compute(p);
233	
234	    // Determines the exact costs of a likely good layout through Knuth-Plass
235	    // with approximate metrics. We can use this cost as an upper bound to prune
236	    // the search space in our proper optimization pass below.
237	    let upper_bound = linebreak_optimized_approximate(engine, p, width, &metrics);
238	
239	    // Using the upper bound, perform exact optimized linebreaking.
240	    linebreak_optimized_bounded(engine, p, width, &metrics, upper_bound)
241	}
242	
243	/// Performs line breaking in optimized Knuth-Plass style, but with an upper
244	/// bound on the cost. This allows us to skip many parts of the search space.
245	#[typst_macros::time]
246	fn linebreak_optimized_bounded<'a>(
247	    engine: &Engine,
248	    p: &'a Preparation<'a>,
249	    width: Abs,
250	    metrics: &CostMetrics,
251	    upper_bound: Cost,
252	) -> Vec<Line<'a>> {
253	    /// An entry in the dynamic programming table for inline layout optimization.
254	    struct Entry<'a> {
255	        pred: usize,
256	        total: Cost,
257	        line: Line<'a>,
258	        end: usize,
259	    }
260	
261	    // Dynamic programming table.
262	    let mut table = vec![Entry { pred: 0, total: 0.0, line: Line::empty(), end: 0 }];
263	
264	    let mut active = 0;
265	    let mut prev_end = 0;
266	
267	    breakpoints(p, |end, breakpoint| {
268	        // Find the optimal predecessor.
269	        let mut best: Option<Entry> = None;
270	
271	        // A lower bound for the cost of all following line attempts.
272	        let mut line_lower_bound = None;
273	
274	        for (pred_index, pred) in table.iter().enumerate().skip(active) {
275	            let start = pred.end;
276	            let unbreakable = prev_end == start;
277	
278	            // If the minimum cost we've established for the line is already
279	            // too much, skip this attempt.
280	            if line_lower_bound
281	                .is_some_and(|lower| pred.total + lower > upper_bound + BOUND_EPS)
282	            {
283	                continue;
284	            }
285	
286	            // Build the line.
287	            let attempt = line(engine, p, start..end, breakpoint, Some(&pred.line));
288	
289	            // Determine the cost of the line and its stretch ratio.
290	            let (line_ratio, line_cost) = ratio_and_cost(
291	                p,
292	                metrics,
293	                width,
294	                &pred.line,
295	                &attempt,
296	                breakpoint,
297	                unbreakable,
298	            );
299	
300	            // If the line is overfull, we adjust the set of active candidate
301	            // line starts. This is the case if
302	            // - justification is on, but we'd need to shrink too much
303	            // - justification is off and the line just doesn't fit
304	            //
305	            // If this is the earliest breakpoint in the active set
306	            // (active == i), remove it from the active set. If there is an
307	            // earlier one (active < i), then the logically shorter line was
308	            // in fact longer (can happen with negative spacing) and we
309	            // can't trim the active set just yet.
310	            if line_ratio < metrics.min_ratio && active == pred_index {
311	                active += 1;
312	            }
313	
314	            // The total cost of this line and its chain of predecessors.
315	            let total = pred.total + line_cost;
316	
317	            // If the line is already underfull (`line_ratio > 0`), any shorter
318	            // slice of the line will be even more underfull. So it'll only get
319	            // worse from here and further attempts would also have a cost
320	            // exceeding `bound`. There is one exception: When the line has
321	            // negative spacing, we can't know for sure, so we don't assign the
322	            // lower bound in that case.
323	            if line_ratio > 0.0
324	                && line_lower_bound.is_none()
325	                && !attempt.has_negative_width_items()
326	            {
327	                line_lower_bound = Some(line_cost);
328	            }
329	
330	            // If the cost already exceeds the upper bound, we don't need to
331	            // integrate this result into the table.
332	            if total > upper_bound + BOUND_EPS {
333	                continue;
334	            }
335	
336	            // If this attempt is better than what we had before, take it!
337	            if best.as_ref().is_none_or(|best| best.total >= total) {
338	                best = Some(Entry { pred: pred_index, total, line: attempt, end });
339	            }
340	        }
341	
342	        // If this is a mandatory break, all breakpoints before this one become
343	        // inactive since no line can span over the mandatory break.
344	        if breakpoint == Breakpoint::Mandatory {
345	            active = table.len();
346	        }
347	
348	        table.extend(best);
349	        prev_end = end;
350	    });
351	
352	    // Retrace the best path.
353	    let mut lines = Vec::with_capacity(16);
354	    let mut idx = table.len() - 1;
355	
356	    // This should only happen if our bound was faulty. Which shouldn't happen!
357	    if table[idx].end != p.text.len() {
358	        #[cfg(debug_assertions)]
359	        panic!("bounded inline layout is incomplete");
360	
361	        #[cfg(not(debug_assertions))]
362	        return linebreak_optimized_bounded(engine, p, width, metrics, Cost::INFINITY);
363	    }
364	
365	    while idx != 0 {
366	        table.truncate(idx + 1);
367	        let entry = table.pop().unwrap();
368	        lines.push(entry.line);
369	        idx = entry.pred;
370	    }
371	
372	    lines.reverse();
373	    lines
374	}
375	
376	/// Runs the normal Knuth-Plass algorithm, but instead of building proper lines
377	/// (which is costly) to determine costs, it determines approximate costs using
378	/// cumulative arrays.
379	///
380	/// This results in a likely good inline layouts, for which we then compute
381	/// the exact cost. This cost is an upper bound for proper optimized
382	/// linebreaking. We can use it to heavily prune the search space.
383	#[typst_macros::time]
384	fn linebreak_optimized_approximate(
385	    engine: &Engine,
386	    p: &Preparation,
387	    width: Abs,
388	    metrics: &CostMetrics,
389	) -> Cost {
390	    // Determine the cumulative estimation metrics.
391	    let estimates = Estimates::compute(p);
392	
393	    /// An entry in the dynamic programming table for inline layout optimization.
394	    struct Entry {
395	        pred: usize,
396	        total: Cost,
397	        end: usize,
398	        unbreakable: bool,
399	        breakpoint: Breakpoint,
400	    }
401	
402	    // Dynamic programming table.
403	    let mut table = vec![Entry {
404	        pred: 0,
405	        total: 0.0,
406	        end: 0,
407	        unbreakable: false,
408	        breakpoint: Breakpoint::Mandatory,
409	    }];
410	
411	    let mut active = 0;
412	    let mut prev_end = 0;
413	
414	    breakpoints(p, |end, breakpoint| {
415	        // Find the optimal predecessor.
416	        let mut best: Option<Entry> = None;
417	        for (pred_index, pred) in table.iter().enumerate().skip(active) {
418	            let start = pred.end;
419	            let unbreakable = prev_end == start;
420	
421	            // Whether the line is justified. This is not 100% accurate w.r.t
422	            // to line()'s behaviour, but good enough.
423	            let justify = p.config.justify && breakpoint != Breakpoint::Mandatory;
424	
425	            // We don't really know whether the line naturally ends with a dash
426	            // here, so we can miss that case, but it's ok, since all of this
427	            // just an estimate.
428	            let consecutive_dash = pred.breakpoint.is_hyphen() && breakpoint.is_hyphen();
429	
430	            // Estimate how much the line's spaces would need to be stretched to
431	            // make it the desired width. We trim at the end to not take into
432	            // account trailing spaces. This is, again, only an approximation of
433	            // the real behaviour of `line`.
434	            let trimmed_end = start + p.text[start..end].trim_end().len();
435	            let line_ratio = raw_ratio(
436	                p,
437	                width,
438	                estimates.widths.estimate(start..trimmed_end)
439	                    + if breakpoint.is_hyphen() {
440	                        metrics.approx_hyphen_width
441	                    } else {
442	                        Abs::zero()
443	                    },
444	                estimates.stretchability.estimate(start..trimmed_end),
445	                estimates.shrinkability.estimate(start..trimmed_end),
446	                estimates.justifiables.estimate(start..trimmed_end),
447	            );
448	
449	            // Determine the line's cost.
450	            let line_cost = raw_cost(
451	                metrics,
452	                breakpoint,
453	                line_ratio,
454	                justify,
455	                unbreakable,
456	                consecutive_dash,
457	                true,
458	            );
459	
460	            // Adjust the set of active breakpoints.
461	            // See `linebreak_optimized` for details.
462	            if line_ratio < metrics.min_ratio && active == pred_index {
463	                active += 1;
464	            }
465	
466	            // The total cost of this line and its chain of predecessors.
467	            let total = pred.total + line_cost;
468	
469	            // If this attempt is better than what we had before, take it!
470	            if best.as_ref().is_none_or(|best| best.total >= total) {
471	                best = Some(Entry {
472	                    pred: pred_index,
473	                    total,
474	                    end,
475	                    unbreakable,
476	                    breakpoint,
477	                });
478	            }
479	        }
480	
481	        // If this is a mandatory break, all breakpoints before this one become
482	        // inactive.
483	        if breakpoint == Breakpoint::Mandatory {
484	            active = table.len();
485	        }
486	
487	        table.extend(best);
488	        prev_end = end;
489	    });
490	
491	    // Retrace the best path.
492	    let mut indices = Vec::with_capacity(16);
493	    let mut idx = table.len() - 1;
494	    while idx != 0 {
495	        indices.push(idx);
496	        idx = table[idx].pred;
497	    }
498	
499	    let mut pred = Line::empty();
500	    let mut start = 0;
501	    let mut exact = 0.0;
502	
503	    // The cost that we optimized was only an approximate cost, so the layout we
504	    // got here is only likely to be good, not guaranteed to be the best. We now
505	    // computes its exact cost as that gives us a sound upper bound for the
506	    // proper optimization pass.
507	    for idx in indices.into_iter().rev() {
508	        let Entry { end, breakpoint, unbreakable, .. } = table[idx];
509	
510	        let attempt = line(engine, p, start..end, breakpoint, Some(&pred));
511	        let (ratio, line_cost) =
512	            ratio_and_cost(p, metrics, width, &pred, &attempt, breakpoint, unbreakable);
513	
514	        // If approximation produces a valid layout without too much shrinking,
515	        // exact layout is guaranteed to find the same layout. If, however, the
516	        // line is overfull, we do not have this guarantee. Then, our bound
517	        // becomes useless and actively harmful (it could be lower than what
518	        // optimal layout produces). Thus, we immediately bail with an infinite
519	        // bound in this case.
520	        if ratio < metrics.min_ratio {
521	            return Cost::INFINITY;
522	        }
523	
524	        pred = attempt;
525	        start = end;
526	        exact += line_cost;
527	    }
528	
529	    exact
530	}
531	
532	/// Compute the stretch ratio and cost of a line.
533	fn ratio_and_cost(
534	    p: &Preparation,
535	    metrics: &CostMetrics,
536	    available_width: Abs,
537	    pred: &Line,
538	    attempt: &Line,
539	    breakpoint: Breakpoint,
540	    unbreakable: bool,
541	) -> (f64, Cost) {
542	    let ratio = raw_ratio(
543	        p,
544	        available_width,
545	        attempt.width,
546	        attempt.stretchability(),
547	        attempt.shrinkability(),
548	        attempt.justifiables(),
549	    );
550	
551	    let cost = raw_cost(
552	        metrics,
553	        breakpoint,
554	        ratio,
555	        attempt.justify,
556	        unbreakable,
557	        pred.dash.is_some() && attempt.dash.is_some(),
558	        false,
559	    );
560	
561	    (ratio, cost)
562	}
563	
564	/// Determine the stretch ratio for a line given raw metrics.
565	///
566	/// - A ratio less than [`CostMetrics::min_ratio`] indicates an overfull line.
567	/// - A negative ratio indicates a line that needs shrinking.
568	/// - A ratio of zero indicates a perfect line.
569	/// - A positive ratio indicates a line that needs stretching.
570	fn raw_ratio(
571	    p: &Preparation,
572	    available_width: Abs,
573	    line_width: Abs,
574	    stretchability: Abs,
575	    shrinkability: Abs,
576	    justifiables: usize,
577	) -> f64 {
578	    // Determine how much the line's spaces would need to be stretched
579	    // to make it the desired width.
580	    let mut delta = available_width - line_width;
581	
582	    // Avoid possible floating point errors in previous calculation.
583	    if delta.approx_eq(Abs::zero()) {
584	        delta = Abs::zero();
585	    }
586	
587	    // Determine how much stretch or shrink is natural.
588	    let adjustability = if delta >= Abs::zero() { stretchability } else { shrinkability };
589	
590	    // Observations:
591	    // - `delta` is negative for a line that needs shrinking and positive for a
592	    //   line that needs stretching.
593	    // - `adjustability` must be non-negative to make sense.
594	    // - `ratio` inherits the sign of `delta`.
595	    let mut ratio = delta / adjustability.max(Abs::zero());
596	
597	    // The most likely cause of a NaN result is that `delta` was zero. This
598	    // often happens with monospace fonts and CJK texts. It means that the line
599	    // already fits perfectly, so `ratio` should be zero then.
600	    if ratio.is_nan() {
601	        ratio = 0.0;
602	    }
603	
604	    // If the ratio exceeds 1, we should stretch above the natural
605	    // stretchability using justifiables.
606	    if ratio > 1.0 {
607	        // We should stretch the line above its stretchability. Now
608	        // calculate the extra amount. Also, don't divide by zero.
609	        let extra_stretch = (delta - adjustability) / justifiables.max(1) as f64;
610	        // Normalize the amount by half the em size.
611	        ratio = 1.0 + extra_stretch / (p.config.font_size / 2.0);
612	    }
613	
614	    // The min value must be < MIN_RATIO, but how much smaller doesn't matter
615	    // since overfull lines have hard-coded huge costs anyway.
616	    //
617	    // The max value is clamped to 10 since it doesn't really matter whether a
618	    // line is stretched 10x or 20x.
619	    ratio.clamp(MIN_RATIO - 1.0, 10.0)
620	}
621	
622	/// Compute the cost of a line given raw metrics.
623	///
624	/// This mostly follows the formula in the Knuth-Plass paper, but there are some
625	/// adjustments.
626	fn raw_cost(
627	    metrics: &CostMetrics,
628	    breakpoint: Breakpoint,
629	    ratio: f64,
630	    justify: bool,
631	    unbreakable: bool,
632	    consecutive_dash: bool,
633	    approx: bool,
634	) -> Cost {
635	    // Determine the stretch/shrink cost of the line.
636	    let badness = if ratio < metrics.min_ratio(approx) {
637	        // Overfull line always has maximum cost.
638	        1_000_000.0
639	    } else if breakpoint != Breakpoint::Mandatory || justify || ratio < 0.0 {
640	        // If the line shall be justified or needs shrinking, it has normal
641	        // badness with cost 100|ratio|^3. We limit the ratio to 10 as to not
642	        // get to close to our maximum cost.
643	        100.0 * Scalar::new(ratio.abs()).powi(3).get()
644	    } else {
645	        // If the line shouldn't be justified and doesn't need shrink, we don't
646	        // pay any cost.
647	        0.0
648	    };
649	
650	    // Compute penalties.
651	    let mut penalty = 0.0;
652	
653	    // Penalize runts (lone words before a mandatory break / at the end).
654	    if unbreakable && breakpoint == Breakpoint::Mandatory {
655	        penalty += metrics.runt_cost;
656	    }
657	
658	    // Penalize hyphenation.
659	    if let Breakpoint::Hyphen(l, r) = breakpoint {
660	        // We penalize hyphenations close to the edges of the word (< LIMIT
661	        // chars) extra. For each step of distance from the limit, we add 15%
662	        // to the cost.
663	        const LIMIT: u8 = 5;
664	        let steps = LIMIT.saturating_sub(l) + LIMIT.saturating_sub(r);
665	        let extra = 0.15 * steps as f64;
666	        penalty += (1.0 + extra) * metrics.hyph_cost;
667	    }
668	
669	    // Penalize two consecutive dashes extra (not necessarily hyphens).
670	    // Knuth-Plass does this separately after the squaring, with a higher cost,
671	    // but I couldn't find any explanation as to why.
672	    if consecutive_dash {
673	        penalty += metrics.hyph_cost;
674	    }
675	
676	    // From the Knuth-Plass Paper: $ (1 + beta_j + pi_j)^2 $.
677	    //
678	    // We add one to minimize the number of lines when everything else is more
679	    // or less equal.
680	    Scalar::new(1.0 + badness + penalty).powi(2).get()
681	}
682	
683	/// Calls `f` for all possible points in the text where lines can broken.
684	///
685	/// Yields for each breakpoint the text index, whether the break is mandatory
686	/// (after `\n`) and whether a hyphen is required (when breaking inside of a
687	/// word).
688	///
689	/// This is an internal instead of an external iterator because it makes the
690	/// code much simpler and the consumers of this function don't need the
691	/// composability and flexibility of external iteration anyway.
692	fn breakpoints(p: &Preparation, mut f: impl FnMut(usize, Breakpoint)) {
693	    let text = p.text;
694	
695	    // Single breakpoint at the end for empty text.
696	    if text.is_empty() {
697	        f(0, Breakpoint::Mandatory);
698	        return;
699	    }
700	
701	    let hyphenate = p.config.hyphenate != Some(false);
702	    let segmenter = match p.config.lang {
703	        Some(Lang::CHINESE | Lang::JAPANESE) => CJ_SEGMENTER.as_borrowed(),
704	        _ => *SEGMENTER,
705	    };
706	
707	    let mut last = 0;
708	    let mut iter = segmenter.segment_str(text).peekable();
709	
710	    loop {
711	        // Special case for links. UAX #14 doesn't handle them well.
712	        let (head, tail) = text.split_at(last);
713	        if head.ends_with("://") || tail.starts_with("www.") {
714	            let (link, _) = link_prefix(tail);
715	            linebreak_link(link, |i| f(last + i, Breakpoint::Normal));
716	            last += link.len();
717	            while iter.peek().is_some_and(|&p| p < last) {
718	                iter.next();
719	            }
720	        }
721	
722	        // Get the next UAX #14 linebreak opportunity.
723	        let Some(point) = iter.next() else { break };
724	
725	        // Skip breakpoint if there is no char before it. icu4x generates one
726	        // at offset 0, but we don't want it.
727	        let Some(c) = text[..point].chars().next_back() else { continue };
728	
729	        // Find out whether the last break was mandatory by checking against
730	        // rules LB4 and LB5, special-casing the end of text according to LB3.
731	        // See also: https://docs.rs/icu_segmenter/latest/icu_segmenter/struct.LineSegmenter.html
732	        let breakpoint = if point == text.len() {
733	            Breakpoint::Mandatory
734	        } else {
735	            const OBJ_REPLACE: char = '\u{FFFC}';
736	            match LINEBREAK_DATA.get(c) {
737	                LineBreak::MandatoryBreak
738	                | LineBreak::CarriageReturn
739	                | LineBreak::LineFeed
740	                | LineBreak::NextLine => Breakpoint::Mandatory,
741	
742	                // https://github.com/typst/typst/issues/5489
743	                //
744	                // OBJECT-REPLACEMENT-CHARACTERs provide Contingent Break
745	                // opportunities before and after by default. This behaviour
746	                // is however tailorable, see:
747	                // https://www.unicode.org/reports/tr14/#CB
748	                // https://www.unicode.org/reports/tr14/#TailorableBreakingRules
749	                // https://www.unicode.org/reports/tr14/#LB20
750	                //
751	                // Don't provide a line breaking opportunity between a LTR-
752	                // ISOLATE (or any other Combining Mark) and an OBJECT-
753	                // REPLACEMENT-CHARACTER representing an inline item, if the
754	                // LTR-ISOLATE could end up as the only character on the
755	                // previous line.
756	                LineBreak::CombiningMark
757	                    if text[point..].starts_with(OBJ_REPLACE)
758	                        && last + c.len_utf8() == point =>
759	                {
760	                    continue;
761	                }
762	
763	                _ => Breakpoint::Normal,
764	            }
765	        };
766	
767	        // Hyphenate between the last and current breakpoint.
768	        if hyphenate && last < point {
769	            for segment in text[last..point].split_word_bounds() {
770	                if !segment.is_empty() && segment.chars().all(char::is_alphabetic) {
771	                    hyphenations(p, last, segment, &mut f);
772	                }
773	                last += segment.len();
774	            }
775	        }
776	
777	        // Call `f` for the UAX #14 break opportunity.
778	        f(point, breakpoint);
779	        last = point;
780	    }
781	}
782	
783	/// Generate breakpoints for hyphenations within a word.
784	fn hyphenations(
785	    p: &Preparation,
786	    mut offset: usize,
787	    word: &str,
788	    mut f: impl FnMut(usize, Breakpoint),
789	) {
790	    let Some(lang) = lang_at(p, offset) else { return };
791	    let count = word.chars().count();
792	    let end = offset + word.len();
793	
794	    let mut chars = 0;
795	    for syllable in hypher::hyphenate(word, lang) {
796	        offset += syllable.len();
797	        chars += syllable.chars().count();
798	
799	        // Don't hyphenate after the final syllable.
800	        if offset == end {
801	            continue;
802	        }
803	
804	        // Filter out hyphenation opportunities where hyphenation was actually
805	        // disabled.
806	        if !hyphenate_at(p, offset) {
807	            continue;
808	        }
809	
810	        // Filter out forbidden hyphenation opportunities.
811	        if matches!(
812	            syllable.chars().next_back().map(|c| LINEBREAK_DATA.get(c)),
813	            Some(LineBreak::Glue | LineBreak::WordJoiner | LineBreak::ZWJ)
814	        ) {
815	            continue;
816	        }
817	
818	        // Determine the number of codepoints before and after the hyphenation.
819	        let l = chars.saturating_as::<u8>();
820	        let r = (count - chars).saturating_as::<u8>();
821	
822	        // Call `f` for the word-internal hyphenation opportunity.
823	        f(offset, Breakpoint::Hyphen(l, r));
824	    }
825	}
826	
827	/// Produce linebreak opportunities for a link.
828	fn linebreak_link(link: &str, mut f: impl FnMut(usize)) {
829	    #[derive(PartialEq)]
830	    enum Class {
831	        Alphabetic,
832	        Digit,
833	        Open,
834	        Other,
835	    }
836	
837	    impl Class {
838	        fn of(c: char) -> Self {
839	            if c.is_alphabetic() {
840	                Class::Alphabetic
841	            } else if c.is_numeric() {
842	                Class::Digit
843	            } else if matches!(c, '(' | '[') {
844	                Class::Open
845	            } else {
846	                Class::Other
847	            }
848	        }
849	    }
850	
851	    let mut offset = 0;
852	    let mut prev = Class::Other;
853	
854	    for (end, c) in link.char_indices() {
855	        let class = Class::of(c);
856	
857	        // Emit opportunities when going from
858	        // - other -> other
859	        // - alphabetic -> numeric
860	        // - numeric -> alphabetic
861	        // Never before/after opening delimiters.
862	        if end > 0
863	            && prev != Class::Open
864	            && if class == Class::Other { prev == Class::Other } else { class != prev }
865	        {
866	            let piece = &link[offset..end];
867	            if piece.len() < 16 {
868	                // For bearably long segments, emit them as one.
869	                offset = end;
870	                f(offset);
871	            } else {
872	                // If it gets very long (e.g. a hash in the URL), just allow a
873	                // break at every char.
874	                for c in piece.chars() {
875	                    offset += c.len_utf8();
876	                    f(offset);
877	                }
878	            }
879	        }
880	
881	        prev = class;
882	    }
883	}
884	
885	/// Whether hyphenation is enabled at the given offset.
886	fn hyphenate_at(p: &Preparation, offset: usize) -> bool {
887	    p.config.hyphenate.unwrap_or_else(|| {
888	        let (_, item) = p.get(offset);
889	        match item.text() {
890	            Some(text) => {
891	                text.styles.get(TextElem::hyphenate).unwrap_or(p.config.justify)
892	            }
893	            None => false,
894	        }
895	    })
896	}
897	
898	/// The text language at the given offset.
899	fn lang_at(p: &Preparation, offset: usize) -> Option<hypher::Lang> {
900	    let lang = p.config.lang.or_else(|| {
901	        let (_, item) = p.get(offset);
902	        let styles = item.text()?.styles;
903	        Some(styles.get(TextElem::lang))
904	    })?;
905	
906	    let bytes = lang.as_str().as_bytes().try_into().ok()?;
907	    hypher::Lang::from_iso(bytes)
908	}
909	
910	/// Resolved metrics relevant for cost computation.
911	struct CostMetrics {
912	    min_ratio: f64,
913	    min_approx_ratio: f64,
914	    approx_hyphen_width: Abs,
915	    hyph_cost: Cost,
916	    runt_cost: Cost,
917	}
918	
919	impl CostMetrics {
920	    /// Compute shared metrics for inline layout optimization.
921	    fn compute(p: &Preparation) -> Self {
922	        Self {
923	            // When justifying, we may stretch spaces below their natural width.
924	            min_ratio: if p.config.justify { MIN_RATIO } else { 0.0 },
925	            min_approx_ratio: if p.config.justify { MIN_APPROX_RATIO } else { 0.0 },
926	            // Approximate hyphen width for estimates.
927	            approx_hyphen_width: Em::new(0.33).at(p.config.font_size),
928	            // Costs.
929	            hyph_cost: DEFAULT_HYPH_COST * p.config.costs.hyphenation().get(),
930	            runt_cost: DEFAULT_RUNT_COST * p.config.costs.runt().get(),
931	        }
932	    }
933	
934	    /// The minimum line ratio we allow for shrinking. For approximate layout,
935	    /// we allow less because otherwise we get an invalid layout fairly often,
936	    /// which makes our bound useless.
937	    fn min_ratio(&self, approx: bool) -> f64 {
938	        if approx { self.min_approx_ratio } else { self.min_ratio }
939	    }
940	}
941	
942	/// Estimated line metrics.
943	///
944	/// Allows to get a quick estimate of a metric for a line between two byte
945	/// positions.
946	struct Estimates {
947	    widths: CumulativeVec<Abs>,
948	    stretchability: CumulativeVec<Abs>,
949	    shrinkability: CumulativeVec<Abs>,
950	    justifiables: CumulativeVec<usize>,
951	}
952	
953	impl Estimates {
954	    /// Compute estimations for approximate Knuth-Plass layout.
955	    fn compute(p: &Preparation) -> Self {
956	        let cap = p.text.len();
957	
958	        let mut widths = CumulativeVec::with_capacity(cap);
959	        let mut stretchability = CumulativeVec::with_capacity(cap);
960	        let mut shrinkability = CumulativeVec::with_capacity(cap);
961	        let mut justifiables = CumulativeVec::with_capacity(cap);
962	
963	        for (range, item) in &p.items {
964	            if let Item::Text(shaped) = item {
965	                for g in shaped.glyphs.iter() {
966	                    let byte_len = g.range.len();
967	                    let stretch = g.stretchability().0 + g.stretchability().1;
968	                    let shrink = g.shrinkability().0 + g.shrinkability().1;
969	                    widths.push(byte_len, g.x_advance.at(g.size));
970	                    stretchability.push(byte_len, stretch.at(g.size));
971	                    shrinkability.push(byte_len, shrink.at(g.size));
972	                    justifiables.push(byte_len, g.is_justifiable() as usize);
973	                }
974	            } else {
975	                widths.push(range.len(), item.natural_width());
976	            }
977	
978	            widths.adjust(range.end);
979	            stretchability.adjust(range.end);
980	            shrinkability.adjust(range.end);
981	            justifiables.adjust(range.end);
982	        }
983	
984	        Self {
985	            widths,
986	            stretchability,
987	            shrinkability,
988	            justifiables,
989	        }
990	    }
991	}
992	
993	/// An accumulative array of a metric.
994	struct CumulativeVec<T> {
995	    total: T,
996	    summed: Vec<T>,
997	}
998	
999	impl<T> CumulativeVec<T>
1000	where
1001	    T: Default + Copy + Add<Output = T> + Sub<Output = T>,
1002	{
1003	    /// Create a new instance with the given capacity.
1004	    fn with_capacity(capacity: usize) -> Self {
1005	        let total = T::default();
1006	        let mut summed = Vec::with_capacity(capacity);
1007	        summed.push(total);
1008	        Self { total, summed }
1009	    }
1010	
1011	    /// Adjust to cover the given byte length.
1012	    fn adjust(&mut self, len: usize) {
1013	        self.summed.resize(len, self.total);
1014	    }
1015	
1016	    /// Adds a new segment with the given byte length and metric.
1017	    fn push(&mut self, byte_len: usize, metric: T) {
1018	        self.total = self.total + metric;
1019	        for _ in 0..byte_len {
1020	            self.summed.push(self.total);
1021	        }
1022	    }
1023	
1024	    /// Estimates the metrics for the line spanned by the range.
1025	    #[track_caller]
1026	    fn estimate(&self, range: Range) -> T {
1027	        self.get(range.end) - self.get(range.start)
1028	    }
1029	
1030	    /// Get the metric at the given byte position.
1031	    #[track_caller]
1032	    fn get(&self, index: usize) -> T {
1033	        match index.checked_sub(1) {
1034	            None => T::default(),
1035	            Some(i) => self.summed[i],
1036	        }
1037	    }
1038	}
