16	const SHY: char = '\u{ad}';
17	const HYPHEN: char = '-';
18	const EN_DASH: char = '–';
19	const EM_DASH: char = '—';
20	const LINE_SEPARATOR: char = '\u{2028}'; // We use LS to distinguish justified breaks.
