22	/// A layouted line, consisting of a sequence of layouted inline items that are
23	/// mostly borrowed from the preparation phase. This type enables you to measure
24	/// the size of a line in a range before committing to building the line's
25	/// frame.
26	///
27	/// At most two inline items must be created individually for this line: The
28	/// first and last one since they may be broken apart by the start or end of the
29	/// line, respectively. But even those can partially reuse previous results when
30	/// the break index is safe-to-break per rustybuzz.
31	pub struct Line<'a> {
32	    /// The items the line is made of.
33	    pub items: Items<'a>,
34	    /// The exact natural width of the line.
35	    pub width: Abs,
36	    /// Whether the line should be justified.
37	    pub justify: bool,
38	    /// Whether the line ends with a hyphen or dash, either naturally or through
39	    /// hyphenation.
40	    pub dash: Option<Dash>,
41	}
42	
43	impl Line<'_> {
44	    /// Create an empty line.
45	    pub fn empty() -> Self {
46	        Self {
47	            items: Items::new(),
48	            width: Abs::zero(),
49	            justify: false,
50	            dash: None,
51	        }
52	    }
53	
54	    /// How many glyphs are in the text where we can insert additional
55	    /// space when encountering underfull lines.
56	    pub fn justifiables(&self) -> usize {
57	        let mut count = 0;
58	        for shaped in self.items.iter().filter_map(Item::text) {
59	            count += shaped.justifiables();
60	        }
61	
62	        // CJK character at line end should not be adjusted.
63	        if self
64	            .items
65	            .trailing_text()
66	            .map(|s| s.cjk_justifiable_at_last())
67	            .unwrap_or(false)
68	        {
69	            count -= 1;
70	        }
71	
72	        count
73	    }
74	
75	    /// How much the line can stretch.
76	    pub fn stretchability(&self) -> Abs {
77	        self.items
78	            .iter()
79	            .filter_map(Item::text)
80	            .map(|s| s.stretchability())
81	            .sum()
82	    }
83	
84	    /// How much the line can shrink.
85	    pub fn shrinkability(&self) -> Abs {
86	        self.items
87	            .iter()
88	            .filter_map(Item::text)
89	            .map(|s| s.shrinkability())
90	            .sum()
91	    }
92	
93	    /// Whether the line has items with negative width.
94	    pub fn has_negative_width_items(&self) -> bool {
95	        self.items.iter().any(|item| match item {
96	            Item::Absolute(amount, _) => *amount < Abs::zero(),
97	            Item::Frame(frame) => frame.width() < Abs::zero(),
98	            _ => false,
99	        })
100	    }
101	
102	    /// The sum of fractions in the line.
103	    pub fn fr(&self) -> Fr {
104	        self.items
105	            .iter()
106	            .filter_map(|item| match item {
107	                Item::Fractional(fr, _) => Some(*fr),
108	                _ => None,
109	            })
110	            .sum()
111	    }
112	}
