114	/// A dash at the end of a line.
115	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
116	pub enum Dash {
117	    /// A soft hyphen added to break a word.
118	    Soft,
119	    /// A regular hyphen, present in a compound word, e.g. beija-flor.
120	    Hard,
121	    /// Another kind of dash. Only relevant for cost computation.
122	    Other,
123	}
124	
125	/// Create a line which spans the given range.
126	pub fn line<'a>(
127	    engine: &Engine,
128	    p: &'a Preparation,
129	    range: Range,
130	    breakpoint: Breakpoint,
131	    pred: Option<&Line<'a>>,
132	) -> Line<'a> {
133	    // The line's full text.
134	    let full = &p.text[range.clone()];
135	
136	    // Whether the line is justified.
137	    let justify = full.ends_with(LINE_SEPARATOR)
138	        || (p.config.justify && breakpoint != Breakpoint::Mandatory);
139	
140	    // Process dashes.
141	    let dash = if breakpoint.is_hyphen() || full.ends_with(SHY) {
142	        Some(Dash::Soft)
143	    } else if full.ends_with(HYPHEN) {
144	        Some(Dash::Hard)
145	    } else if full.ends_with([EN_DASH, EM_DASH]) {
146	        Some(Dash::Other)
147	    } else {
148	        None
149	    };
150	
151	    // Trim the line at the end, if necessary for this breakpoint.
152	    let trim = breakpoint.trim(range.start, full);
153	    let trimmed_range = range.start..trim.layout;
154	
155	    // Collect the items for the line.
156	    let mut items = Items::new();
157	
158	    // Add a hyphen at the line start, if a previous dash should be repeated.
159	    if let Some(pred) = pred
160	        && pred.dash == Some(Dash::Hard)
161	        && let Some(base) = pred.items.trailing_text()
162	        && should_repeat_hyphen(base.lang, full)
163	        && let Some(hyphen) =
164	            ShapedText::hyphen(engine, p.config.fallback, base, trim.shaping, false)
165	    {
166	        items.push(Item::Text(hyphen), LogicalIndex::START_HYPHEN);
167	    }
168	
169	    collect_items(&mut items, engine, p, range, &trim);
170	
171	    // Add a hyphen at the line end, if we ended on a soft hyphen.
172	    if dash == Some(Dash::Soft)
173	        && let Some(base) = items.trailing_text()
174	        && let Some(hyphen) =
175	            ShapedText::hyphen(engine, p.config.fallback, base, trim.shaping, true)
176	    {
177	        items.push(Item::Text(hyphen), LogicalIndex::END_HYPHEN);
178	    }
179	
180	    // Ensure that there is no weak spacing at the start and end of the line.
181	    trim_weak_spacing(&mut items);
182	
183	    // Deal with CJ characters at line boundaries.
184	    // Use the trimmed range for robust boundary checks.
185	    adjust_cj_at_line_boundaries(p, trimmed_range, &mut items);
186	
187	    // Deal with stretchability of glyphs at the end of the line.
188	    adjust_glyph_stretch_at_line_end(p, &mut items);
189	
190	    // Compute the line's width.
191	    let width = items.iter().map(Item::natural_width).sum();
192	
193	    Line { items, width, justify, dash }
194	}
