196	/// Collects / reshapes all items for the line with the given `range`.
197	///
198	/// The `trim` defines an end position to which text items are trimmed. For
199	/// example, the `range` may span "hello\n", but the `trim` specifies that the
200	/// linebreak is trimmed.
201	///
202	/// We do not factor the `trim` directly into the `range` because we still want
203	/// to keep non-text items after the trim (e.g. tags).
204	fn collect_items<'a>(
205	    items: &mut Items<'a>,
206	    engine: &Engine,
207	    p: &'a Preparation,
208	    range: Range,
209	    trim: &Trim,
210	) {
211	    let mut fallback = None;
212	
213	    // Collect the items for each consecutively ordered run.
214	    reorder(p, range.clone(), |subrange, rtl| {
215	        let from = items.len();
216	        collect_range(engine, p, subrange, trim, items, &mut fallback);
217	        if rtl {
218	            items.reorder(from);
219	        }
220	    });
221	
222	    // Add fallback text to expand the line height, if necessary.
223	    if !items.iter().any(|item| matches!(item, Item::Text(_)))
224	        && let Some((idx, fallback)) = fallback
225	    {
226	        items.push(fallback, idx);
227	    }
228	}
229	
230	/// Trims weak spacing from the start and end of the line.
231	fn trim_weak_spacing(items: &mut Items) {
232	    // Trim weak spacing at the start of the line.
233	    let prefix = items
234	        .iter()
235	        .take_while(|item| matches!(item, Item::Absolute(_, true)))
236	        .count();
237	    if prefix > 0 {
238	        items.drain(..prefix);
239	    }
240	
241	    // Trim weak spacing at the end of the line.
242	    while matches!(items.iter().next_back(), Some(Item::Absolute(_, true))) {
243	        items.pop();
244	    }
245	}
246	
247	/// Calls `f` for the BiDi-reordered ranges of a line.
248	fn reorder<F>(p: &Preparation, range: Range, mut f: F)
249	where
250	    F: FnMut(Range, bool),
251	{
252	    // If there is nothing bidirectional going on, skip reordering.
253	    let Some(bidi) = &p.bidi else {
254	        f(range, p.config.dir == Dir::RTL);
255	        return;
256	    };
257	
258	    // The bidi crate panics for empty lines.
259	    if range.is_empty() {
260	        f(range, p.config.dir == Dir::RTL);
261	        return;
262	    }
263	
264	    // Find the paragraph that contains the line.
265	    let para = bidi
266	        .paragraphs
267	        .iter()
268	        .find(|para| para.range.contains(&range.start))
269	        .unwrap();
270	
271	    // Compute the reordered ranges in visual order (left to right).
272	    let (levels, runs) = bidi.visual_runs(para, range.clone());
273	
274	    // Call `f` for each run.
275	    for run in runs {
276	        let rtl = levels[run.start].is_rtl();
277	        f(run, rtl);
278	    }
279	}
280	
281	/// Collects / reshapes all items for the given `subrange` with continuous
282	/// direction.
283	fn collect_range<'a>(
284	    engine: &Engine,
285	    p: &'a Preparation,
286	    range: Range,
287	    trim: &Trim,
288	    items: &mut Items<'a>,
289	    fallback: &mut Option<(LogicalIndex, ItemEntry<'a>)>,
290	) {
291	    for (i, (subrange, item)) in p.slice(range.clone()) {
292	        let idx = LogicalIndex::from_item_index(i);
293	
294	        // All non-text items are just kept, they can't be split.
295	        let Item::Text(shaped) = item else {
296	            items.push(item, idx);
297	            continue;
298	        };
299	
300	        // The intersection range of the item, the subrange, and the line's
301	        // trimming.
302	        let sliced = range.start.max(subrange.start)
303	            ..range.end.min(subrange.end).min(trim.shaping);
304	
305	        // Whether the item is split by the line.
306	        let split = subrange.start < sliced.start || sliced.end < subrange.end;
307	
308	        if sliced.is_empty() {
309	            // When there is no text, still keep this as a fallback item, which
310	            // we can use to force a non-zero line-height when the line doesn't
311	            // contain any other text.
312	            *fallback = Some((idx, ItemEntry::from(Item::Text(shaped.empty()))));
313	            continue;
314	        }
315	
316	        let mut item: ItemEntry = if split {
317	            // When the item is split in half, reshape it.
318	            let reshaped = shaped.reshape(engine, sliced);
319	            Item::Text(reshaped).into()
320	        } else {
321	            // When the item is fully contained, just keep it.
322	            item.into()
323	        };
324	
325	        // Trim end-of-line whitespace glyphs.
326	        if trim.layout < range.end {
327	            let shaped = item.text_mut().unwrap();
328	            // Make sure not to trim glyphs that have overlapping ranges, for
329	            // example due to zero width spaces included in the cluster.
330	            // Otherwise these glyphs would protrude into the margin.
331	            shaped.glyphs.trim(|glyph| glyph.range.start >= trim.layout);
332	        }
333	
334	        items.push(item, idx);
335	    }
336	}
337	
338	/// Add spacing around punctuation marks for CJ glyphs at line boundaries.
339	///
340	/// See Requirements for Chinese Text Layout, Section 3.1.6.3 Compression of
341	/// punctuation marks at line start or line end.
342	///
343	/// The `range` should only contain regular texts, with linebreaks trimmed.
344	fn adjust_cj_at_line_boundaries(p: &Preparation, range: Range, items: &mut Items) {
345	    let text = &p.text[range];
346	
347	    if text.starts_with(BEGIN_PUNCT_PAT)
348	        || (p.config.cjk_latin_spacing && text.starts_with(is_of_cj_script))
349	    {
350	        adjust_cj_at_line_start(p, items);
351	    }
352	
353	    if text.ends_with(END_PUNCT_PAT)
354	        || (p.config.cjk_latin_spacing && text.ends_with(is_of_cj_script))
355	    {
356	        adjust_cj_at_line_end(p, items);
357	    }
358	}
359	
360	/// Remove stretchability from the last glyph in the line to avoid trailing
361	/// space after a glyph due to glyph-level justification.
362	fn adjust_glyph_stretch_at_line_end(p: &Preparation, items: &mut Items) {
363	    let glyph_limits = &p.config.justification_limits.tracking();
364	    if glyph_limits.min.is_zero() && glyph_limits.max.is_zero() {
365	        return;
366	    }
367	
368	    // This is not perfect (ignores clusters and is not particularly fast), but
369	    // it is good enough for now. The adjustability handling in general needs a
370	    // cleanup.
371	    let Some(shaped) = items.trailing_text_mut() else { return };
372	    let Some(glyph) = shaped.glyphs.to_mut().last_mut() else { return };
373	    glyph.adjustability = Adjustability::default();
374	}
375	
376	/// Add spacing around punctuation marks for CJ glyphs at the line start.
377	fn adjust_cj_at_line_start(p: &Preparation, items: &mut Items) {
378	    let Some(shaped) = items.leading_text_mut() else { return };
379	    let Some(glyph) = shaped.glyphs.first() else { return };
380	
381	    if glyph.is_cjk_right_aligned_punctuation() {
382	        // If the first glyph is a CJK punctuation, we want to
383	        // shrink it.
384	        let glyph = shaped.glyphs.to_mut().first_mut().unwrap();
385	        let shrink = glyph.shrinkability().0;
386	        glyph.shrink_left(shrink);
387	    } else if p.config.cjk_latin_spacing
388	        && glyph.is_cj_script()
389	        && glyph.x_offset > Em::zero()
390	    {
391	        // If the first glyph is a CJK character adjusted by
392	        // [`add_cjk_latin_spacing`], restore the original width.
393	        let glyph = shaped.glyphs.to_mut().first_mut().unwrap();
394	        let shrink = glyph.x_offset;
395	        glyph.x_advance -= shrink;
396	        glyph.x_offset = Em::zero();
397	        glyph.adjustability.shrinkability.0 = Em::zero();
398	    }
399	}
400	
401	/// Add spacing around punctuation marks for CJ glyphs at the line end.
402	fn adjust_cj_at_line_end(p: &Preparation, items: &mut Items) {
403	    let Some(shaped) = items.trailing_text_mut() else { return };
404	    let Some(glyph) = shaped.glyphs.last() else { return };
405	
406	    // Deal with CJK punctuation at line ends.
407	    let style = cjk_punct_style(shaped.lang, shaped.region);
408	
409	    if glyph.is_cjk_left_aligned_punctuation(style) {
410	        // If the last glyph is a CJK punctuation, we want to
411	        // shrink it.
412	        let shrink = glyph.shrinkability().1;
413	        let punct = shaped.glyphs.to_mut().last_mut().unwrap();
414	        punct.shrink_right(shrink);
415	    } else if p.config.cjk_latin_spacing
416	        && glyph.is_cj_script()
417	        && (glyph.x_advance - glyph.x_offset) > Em::one()
418	    {
419	        // If the last glyph is a CJK character adjusted by
420	        // [`add_cjk_latin_spacing`], restore the original width.
421	        let shrink = glyph.x_advance - glyph.x_offset - Em::one();
422	        let glyph = shaped.glyphs.to_mut().last_mut().unwrap();
423	        glyph.x_advance -= shrink;
424	        glyph.adjustability.shrinkability.1 = Em::zero();
425	    }
426	}
427	
428	/// Whether a hyphen should be repeated at the start of the line in the given
429	/// language, when the following text is the given one.
430	fn should_repeat_hyphen(lang: Lang, following_text: &str) -> bool {
431	    match lang {
432	        // - Lower Sorbian: see https://dolnoserbski.de/ortografija/psawidla/K3
433	        // - Czech: see https://prirucka.ujc.cas.cz/?id=164
434	        // - Croatian: see http://pravopis.hr/pravilo/spojnica/68/
435	        // - Polish: see https://www.ortograf.pl/zasady-pisowni/lacznik-zasady-pisowni
436	        // - Portuguese: see https://www2.senado.leg.br/bdsf/bitstream/handle/id/508145/000997415.pdf (Base XX)
437	        // - Slovak: see https://www.zones.sk/studentske-prace/gramatika/10620-pravopis-rozdelovanie-slov/
438	        Lang::LOWER_SORBIAN
439	        | Lang::CZECH
440	        | Lang::CROATIAN
441	        | Lang::POLISH
442	        | Lang::PORTUGUESE
443	        | Lang::SLOVAK => true,
444	
445	        // In Spanish the hyphen is required only if the word next to hyphen is
446	        // not capitalized. Otherwise, the hyphen must not be repeated.
447	        //
448	        // See § 4.1.1.1.2.e on the "Ortografía de la lengua española"
449	        // https://www.rae.es/ortografía/como-signo-de-división-de-palabras-a-final-de-línea
450	        Lang::SPANISH => following_text.chars().next().is_some_and(|c| !c.is_uppercase()),
451	
452	        _ => false,
453	    }
454	}
455	
456	/// Apply the current baseline shift and italic compensation to a frame.
457	pub fn apply_shift<'a>(
458	    world: &Tracked<'a, dyn World + 'a>,
459	    frame: &mut Frame,
460	    styles: StyleChain,
461	) {
462	    let mut baseline = styles.resolve(TextElem::baseline);
463	    let mut compensation = Abs::zero();
464	    if let Some(scripts) = styles.get_ref(TextElem::shift_settings) {
465	        let variant = variant(styles);
466	        let size = styles.resolve(TextElem::size);
467	        let variations = styles.get_cloned(TextElem::variations);
468	        let font_metrics = families(styles)
469	            .find_map(|family| {
470	                world
471	                    .book()
472	                    .select(family.as_str(), variant)
473	                    .and_then(|id| world.font(id))
474	                    .map(|font| font.instantiate(variant, size, &variations))
475	            })
476	            .map_or(*scripts.kind.default_metrics(), |f| {
477	                *scripts.kind.read_metrics(f.metrics())
478	            });
479	        baseline -= scripts.shift.unwrap_or(font_metrics.vertical_offset).at(size);
480	        compensation += font_metrics.horizontal_offset.at(size);
481	    }
482	    frame.translate(Point::new(compensation, baseline));
483	}
484	
485	/// Commit to a line and build its frame.
486	pub fn commit(
487	    engine: &mut Engine,
488	    p: &Preparation,
489	    line: &Line,
490	    width: Abs,
491	    full: Abs,
492	    locator: &mut SplitLocator<'_>,
493	) -> SourceResult<Frame> {
494	    let mut remaining = width - line.width - p.config.hanging_indent;
495	    let mut offset = Abs::zero();
496	
497	    // We always build the line from left to right. In an LTR paragraph, we must
498	    // thus add the hanging indent to the offset. In an RTL paragraph, the
499	    // hanging indent arises naturally due to the line width.
500	    if p.config.dir == Dir::LTR {
501	        offset += p.config.hanging_indent;
502	    }
503	
504	    // Handle hanging punctuation to the left.
505	    if let Some(text) = line.items.leading_text()
506	        && let Some(glyph) = text.glyphs.first()
507	        && !text.dir.is_positive()
508	        && text.styles.get(TextElem::overhang)
509	        && (line.items.len() > 1 || text.glyphs.len() > 1)
510	    {
511	        let amount = overhang(glyph.c) * glyph.x_advance.at(glyph.size);
512	        offset -= amount;
513	        remaining += amount;
514	    }
515	
516	    // Handle hanging punctuation to the right.
517	    if let Some(text) = line.items.trailing_text()
518	        && let Some(glyph) = text.glyphs.last()
519	        && text.dir.is_positive()
520	        && text.styles.get(TextElem::overhang)
521	        && (line.items.len() > 1 || text.glyphs.len() > 1)
522	    {
523	        let amount = overhang(glyph.c) * glyph.x_advance.at(glyph.size);
524	        remaining += amount;
525	    }
526	
527	    // Determine how much additional space is needed. The justification_ratio is
528	    // for the first step justification, extra_justification is for the last
529	    // step. For more info on multi-step justification, see Procedures for
530	    // Inter- Character Space Expansion in W3C document Chinese Layout
531	    // Requirements.
532	    let fr = line.fr();
533	    let mut justification_ratio = 0.0;
534	    let mut extra_justification = Abs::zero();
535	
536	    let shrinkability = line.shrinkability();
537	    let stretchability = line.stretchability();
538	    if remaining < Abs::zero() && shrinkability > Abs::zero() {
539	        // Attempt to reduce the length of the line, using shrinkability.
540	        justification_ratio = (remaining / shrinkability).max(-1.0);
541	        remaining = (remaining + shrinkability).min(Abs::zero());
542	    } else if line.justify && fr.is_zero() {
543	        // Attempt to increase the length of the line, using stretchability.
544	        if stretchability > Abs::zero() {
545	            justification_ratio = (remaining / stretchability).min(1.0);
546	            remaining = (remaining - stretchability).max(Abs::zero());
547	        }
548	
549	        let justifiables = line.justifiables();
550	        if justifiables > 0 && remaining > Abs::zero() {
551	            // Underfull line, distribute the extra space.
552	            extra_justification = remaining / justifiables as f64;
553	            remaining = Abs::zero();
554	        }
555	    }
556	
557	    let mut top = Abs::zero();
558	    let mut bottom = Abs::zero();
559	
560	    // Build the frames and determine the height and baseline.
561	    let mut frames = vec![];
562	    for &(idx, ref item) in line.items.indexed_iter() {
563	        let mut push = |offset: &mut Abs, frame: Frame, idx: LogicalIndex| {
564	            let width = frame.width();
565	            top.set_max(frame.baseline());
566	            bottom.set_max(frame.size().y - frame.baseline());
567	            frames.push((*offset, frame, idx));
568	            *offset += width;
569	        };
570	
571	        match &**item {
572	            Item::Absolute(v, _) => {
573	                offset += *v;
574	            }
575	            Item::Fractional(v, elem) => {
576	                let amount = v.share(fr, remaining);
577	                if let Some((elem, loc, styles)) = elem {
578	                    let region = Size::new(amount, full);
579	                    let mut frame = layout_and_modify(*styles, |styles| {
580	                        layout_box(elem, engine, loc.relayout(), styles, region)
581	                    })?;
582	                    apply_shift(&engine.world, &mut frame, *styles);
583	                    push(&mut offset, frame, idx);
584	                } else {
585	                    offset += amount;
586	                }
587	            }
588	            Item::Text(shaped) => {
589	                let frame = shaped.build(
590	                    engine,
591	                    &p.spans,
592	                    justification_ratio,
593	                    extra_justification,
594	                );
595	                push(&mut offset, frame, idx);
596	            }
597	            Item::Frame(frame) => {
598	                push(&mut offset, frame.clone(), idx);
599	            }
600	            Item::Tag(tag) => {
601	                let mut frame = Frame::soft(Size::zero());
602	                frame.push(Point::zero(), FrameItem::Tag((*tag).clone()));
603	                frames.push((offset, frame, idx));
604	            }
605	            Item::Skip(_) => {}
606	        }
607	    }
608	
609	    // Remaining space is distributed now.
610	    if !fr.is_zero() {
611	        remaining = Abs::zero();
612	    }
613	
614	    let size = Size::new(width, top + bottom);
615	    let mut output = Frame::soft(size);
616	    output.set_baseline(top);
617	
618	    if let Some(marker) = &p.config.numbering_marker {
619	        add_par_line_marker(&mut output, marker, engine, locator, top);
620	    }
621	
622	    // Ensure that the final frame's items are in logical order rather than in
623	    // visual order. This is important because it affects the order of elements
624	    // during introspection and thus things like counters.
625	    frames.sort_unstable_by_key(|(_, _, idx)| *idx);
626	
627	    // Construct the line's frame.
628	    for (offset, frame, _) in frames {
629	        let x = offset + p.config.align.position(remaining);
630	        let y = top - frame.baseline();
631	        output.push_frame(Point::new(x, y), frame);
632	    }
633	
634	    Ok(output)
635	}
636	
637	/// Adds a paragraph line marker to a paragraph line's output frame if
638	/// line numbering is not `None` at this point. Ensures other style properties,
639	/// namely number margin, number align and number clearance, are stored in the
640	/// marker as well.
641	///
642	/// The `top` parameter is used to ensure the marker, and thus the line's
643	/// number in the margin, is aligned to the line's baseline.
644	fn add_par_line_marker(
645	    output: &mut Frame,
646	    marker: &Packed<ParLineMarker>,
647	    engine: &mut Engine,
648	    locator: &mut SplitLocator,
649	    top: Abs,
650	) {
651	    // Elements in tags must have a location for introspection to work. We do
652	    // the work here instead of going through all of the realization process
653	    // just for this, given we don't need to actually place the marker as we
654	    // manually search for it in the frame later (when building a root flow,
655	    // where line numbers can be displayed), so we just need it to be in a tag
656	    // and to be valid (to have a location).
657	    let mut marker = marker.clone();
658	    let key = typst_utils::hash128(&marker);
659	    let loc = locator.next_location(engine, key, marker.span());
660	    marker.set_location(loc);
661	
662	    // Create start and end tags through which we can search for this line's
663	    // marker later. The 'x' coordinate is not important, just the 'y'
664	    // coordinate, as that's what is used for line numbers. We will place the
665	    // tags among other subframes in the line such that it is aligned with the
666	    // line's general baseline. However, the line number will still need to
667	    // manually adjust its own 'y' position based on its own baseline.
668	    let pos = Point::with_y(top);
669	    let flags = TagFlags { introspectable: false, tagged: false };
670	    output.push(pos, FrameItem::Tag(Tag::Start(marker.pack(), flags)));
671	    output.push(pos, FrameItem::Tag(Tag::End(loc, key, flags)));
672	}
673	
674	/// How much a character should hang into the end margin.
675	///
676	/// For more discussion, see:
677	/// <https://recoveringphysicist.com/21/>
678	fn overhang(c: char) -> f64 {
679	    match c {
680	        // Dashes.
681	        '–' | '—' => 0.2,
682	        '-' | '\u{ad}' => 0.55,
683	
684	        // Punctuation.
685	        '.' | ',' => 0.8,
686	        ':' | ';' => 0.3,
687	
688	        // Arabic
689	        '\u{60C}' | '\u{6D4}' => 0.4,
690	
691	        _ => 0.0,
692	    }
693	}
694	
695	/// A collection of owned or borrowed inline items.
696	pub struct Items<'a>(Vec<(LogicalIndex, ItemEntry<'a>)>);
697	
698	impl<'a> Items<'a> {
699	    /// Create empty items.
700	    pub fn new() -> Self {
701	        Self(vec![])
702	    }
703	
704	    /// Push a new item.
705	    pub fn push(&mut self, entry: impl Into<ItemEntry<'a>>, idx: LogicalIndex) {
706	        self.0.push((idx, entry.into()));
707	    }
708	
709	    /// Iterate over the items.
710	    pub fn iter(&self) -> impl DoubleEndedIterator<Item = &Item<'a>> {
711	        self.0.iter().map(|(_, item)| &**item)
712	    }
713	
714	    /// Iterate over the items with the indices that define their logical order.
715	    /// See the docs above `logical_item_idx` for more details.
716	    ///
717	    /// Note that this is different from `.iter().enumerate()` which would
718	    /// provide the indices in visual order!
719	    pub fn indexed_iter(
720	        &self,
721	    ) -> impl DoubleEndedIterator<Item = &(LogicalIndex, ItemEntry<'a>)> {
722	        self.0.iter()
723	    }
724	
725	    /// Access the first item (skipping tags), if it is text.
726	    pub fn leading_text(&self) -> Option<&ShapedText<'a>> {
727	        self.0.iter().find(|(_, item)| !item.is_tag())?.1.text()
728	    }
729	
730	    /// Access the first item (skipping tags) mutably, if it is text.
731	    pub fn leading_text_mut(&mut self) -> Option<&mut ShapedText<'a>> {
732	        self.0.iter_mut().find(|(_, item)| !item.is_tag())?.1.text_mut()
733	    }
734	
735	    /// Access the last item (skipping tags), if it is text.
736	    pub fn trailing_text(&self) -> Option<&ShapedText<'a>> {
737	        self.0.iter().rev().find(|(_, item)| !item.is_tag())?.1.text()
738	    }
739	
740	    /// Access the last item (skipping tags) mutably, if it is text.
741	    pub fn trailing_text_mut(&mut self) -> Option<&mut ShapedText<'a>> {
742	        self.0.iter_mut().rev().find(|(_, item)| !item.is_tag())?.1.text_mut()
743	    }
744	
745	    /// Reorder the items starting at the given index to RTL.
746	    pub fn reorder(&mut self, from: usize) {
747	        self.0[from..].reverse();
748	    }
749	}
750	
751	impl<'a> Deref for Items<'a> {
752	    type Target = Vec<(LogicalIndex, ItemEntry<'a>)>;
753	
754	    fn deref(&self) -> &Self::Target {
755	        &self.0
756	    }
757	}
758	
759	impl DerefMut for Items<'_> {
760	    fn deref_mut(&mut self) -> &mut Self::Target {
761	        &mut self.0
762	    }
763	}
764	
765	impl Debug for Items<'_> {
766	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
767	        f.debug_list().entries(&self.0).finish()
768	    }
769	}
770	
771	/// We use indices to remember the logical (as opposed to visual) order of
772	/// items. During line building, the items are stored in visual (BiDi-reordered)
773	/// order. When committing to a line and building its frame, we sort by logical
774	/// index.
775	///
776	/// - Special layout-generated items have custom indices that ensure correct
777	///   ordering w.r.t. to each other and normal elements, listed below.
778	/// - Normal items have their position in `p.items` plus the number of special
779	///   reserved prefix indices.
780	///
781	/// Logical indices must be unique within a line because we use an unstable
782	/// sort.
783	#[derive(Debug, Copy, Clone, Eq, PartialEq, Ord, PartialOrd)]
784	pub struct LogicalIndex(usize);
785	
786	impl LogicalIndex {
787	    const START_HYPHEN: Self = Self(0);
788	    const END_HYPHEN: Self = Self(usize::MAX);
789	
790	    /// Create a logical index from the index of an item in the [`p.items`](Preparation::items).
791	    const fn from_item_index(i: usize) -> Self {
792	        // This won't overflow because the `idx` comes from a vector which is
793	        // limited to `isize::MAX` elements.
794	        Self(i + 1)
795	    }
796	}
797	
798	/// A reference to or a boxed item.
799	///
800	/// This is conceptually similar to a [`Cow<'a, Item<'a>>`][std::borrow::Cow],
801	/// but we box owned items since an [`Item`] is much bigger than
802	/// a box.
803	pub enum ItemEntry<'a> {
804	    Ref(&'a Item<'a>),
805	    Box(Box<Item<'a>>),
806	}
807	
808	impl<'a> ItemEntry<'a> {
809	    fn text_mut(&mut self) -> Option<&mut ShapedText<'a>> {
810	        match self {
811	            Self::Ref(item) => {
812	                let text = item.text()?;
813	                *self = Self::Box(Box::new(Item::Text(text.clone())));
814	                match self {
815	                    Self::Box(item) => item.text_mut(),
816	                    Self::Ref(_) => unreachable!(),
817	                }
818	            }
819	            Self::Box(item) => item.text_mut(),
820	        }
821	    }
822	}
823	
824	impl<'a> Deref for ItemEntry<'a> {
825	    type Target = Item<'a>;
826	
827	    fn deref(&self) -> &Self::Target {
828	        match self {
829	            Self::Ref(item) => item,
830	            Self::Box(item) => item,
831	        }
832	    }
833	}
834	
835	impl Debug for ItemEntry<'_> {
836	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
837	        (**self).fmt(f)
838	    }
839	}
840	
841	impl<'a> From<&'a Item<'a>> for ItemEntry<'a> {
842	    fn from(item: &'a Item<'a>) -> Self {
843	        Self::Ref(item)
844	    }
845	}
846	
847	impl<'a> From<Item<'a>> for ItemEntry<'a> {
848	    fn from(item: Item<'a>) -> Self {
849	        Self::Box(Box::new(item))
850	    }
851	}
